/**
 * @summary List attributes
 */
export type listAttributeResponse200 = {
  data: ListAttribute200;
  status: 200;
};

export type listAttributeResponseSuccess = listAttributeResponse200 & {
  headers: Headers;
};
export type listAttributeResponse = listAttributeResponseSuccess;

export const getListAttributeUrl = (params?: ListAttributeParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/attributes?${stringifiedParams}`
    : `/api/attributes`;
};

export const listAttribute = async (
  params?: ListAttributeParams,
  options?: RequestInit
): Promise<listAttributeResponse> => {
  return customFetch<listAttributeResponse>(getListAttributeUrl(params), {
    ...options,
    method: "GET",
  });
};

