/**
 * @summary Upload a file to storage
 */
export type uploadFileResponse201 = {
  data: UploadFile201;
  status: 201;
};

export type uploadFileResponse400 = {
  data: UploadFile400;
  status: 400;
};

export type uploadFileResponse503 = {
  data: UploadFile503;
  status: 503;
};

export type uploadFileResponseSuccess = uploadFileResponse201 & {
  headers: Headers;
};
export type uploadFileResponseError = (
  uploadFileResponse400 | uploadFileResponse503
) & {
  headers: Headers;
};

export type uploadFileResponse =
  uploadFileResponseSuccess | uploadFileResponseError;

export const getUploadFileUrl = () => {
  return `/api/uploads`;
};

export const uploadFile = async (
  uploadFileBody: UploadFileBody,
  options?: RequestInit
): Promise<uploadFileResponse> => {
  const formData = new FormData();
  formData.append(`file`, uploadFileBody.file);
  if (uploadFileBody.folder !== undefined) {
    formData.append(`folder`, uploadFileBody.folder);
  }

  return customFetch<uploadFileResponse>(getUploadFileUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};
